-- Generated by db/scripts/generate-seed.mjs (end date 2026-10-16). Do not edit by hand.
-- Demo patient: surgery 2026-09-29, drains out 2026-10-09, cording from 2026-10-14.
-- Reloading keeps the patient's record and care plan as a clinician left them (name, phase,
-- exercises, note, sign-in email) and replaces only the generated history.
begin;

on conflict (id) do update set surgery_date = excluded.surgery_date;

-- Sets, reps, symptom logs and band samples go with their sessions. Reports were written from the old history.
delete from sessions where patient_id = '00000000-0000-4000-8000-000000000001';
delete from baselines where patient_id = '00000000-0000-4000-8000-000000000001';
delete from daily_use where patient_id = '00000000-0000-4000-8000-000000000001';
delete from flags where patient_id = '00000000-0000-4000-8000-000000000001';
delete from reports where patient_id = '00000000-0000-4000-8000-000000000001';

-- The default plan, only for a patient who has none yet.
select v.* from (values
  ('00000000-0000-4000-8000-000000000001'::uuid, 1, 'side_raise', 90::real, null::real, 10, 2, 'Demo PT'),
  ('00000000-0000-4000-8000-000000000001'::uuid, 1, 'scaption', 90, null, 10, 2, 'Demo PT'),
  ('00000000-0000-4000-8000-000000000001'::uuid, 2, 'side_raise', null, null, 10, 2, 'Demo PT'),
  ('00000000-0000-4000-8000-000000000001'::uuid, 2, 'scaption', null, null, 10, 2, 'Demo PT')
) as v (patient_id, phase, exercise_id, ceiling_deg, goal_deg, reps_target, sets_target, set_by)
where not exists (select 1 from prescriptions p where p.patient_id = v.patient_id);







-- The band's 20 Hz stream for each exercise session, synthesized in the database so this file
-- stays small: smooth reps (one every ~3.6 s) of varying height up to the session's best, plus sensor noise.
select
  s.patient_id,
  s.id,
  gt.t,
  round((6 + (best.peak - 10) * height.k * (1 - cos(2 * pi() * phase.x)) / 2 + 1.2 * sin(g.n * 1.7))::numeric, 2),
  round((pi() / 3.6 * (best.peak - 10) * height.k * sin(2 * pi() * phase.x))::numeric, 1)
from sessions s
join lateral (select max(r.peak_deg) as peak from reps r join sets st on st.id = r.set_id where st.session_id = s.id) best on true
cross join lateral generate_series(0, (extract(epoch from s.ended_at - s.started_at) * 20)::int) as g(n)
cross join lateral (select s.started_at + g.n * interval '50 milliseconds' as t) gt
cross join lateral (select (g.n / 20.0 / 3.6) % 1 as x) phase
-- Each rep (72 samples) reaches a slightly different height, like real reps do.
cross join lateral (select 0.8 + 0.2 * (0.5 + 0.5 * sin(floor(g.n / 72.0) * 2.4)) as k) height
where s.patient_id = '00000000-0000-4000-8000-000000000001' and s.kind = 'exercise';

commit;
